"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["75222"],{85464(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.modelo_formulario.nao_encontrado","status":404,"titulo":"Modelo de formul\xe1rio n\xe3o encontrado"},"descricao":{"codigo":"uniplus.configuracao.modelo_formulario.nao_encontrado","requisitos":[],"oQueAconteceu":["O `{id}` da rota n\xe3o corresponde a nenhum modelo de formul\xe1rio. A resposta vale para a atualiza\xe7\xe3o (`PUT /api/configuracao/admin/modelos-formulario/{id}`), para a ativa\xe7\xe3o (`POST .../{id}/ativacao`) e para a desativa\xe7\xe3o (`DELETE .../{id}`). O modelo nunca \xe9 apagado, s\xf3 desativado, e a busca encontra tamb\xe9m o modelo desativado: esta causa \xe9 exclusivamente de identificador inexistente. A leitura (`GET .../{id}`), o formul\xe1rio apresentado (`GET .../{id}/apresentacao`) e a pr\xe9-visualiza\xe7\xe3o (`POST .../{id}/pre-visualizacao`) tamb\xe9m respondem 404 para um modelo inexistente, mas essas respostas n\xe3o usam este c\xf3digo.","Nestas tr\xeas opera\xe7\xf5es a busca do modelo vem antes das valida\xe7\xf5es de dom\xednio do conte\xfado: na atualiza\xe7\xe3o, com um `{id}` que n\xe3o existe e um conte\xfado inv\xe1lido, a resposta \xe9 esta, e n\xe3o a recusa do conte\xfado. \xc9 o contr\xe1rio do que ocorre em outros cadastros do m\xf3dulo, em que o conte\xfado do corpo \xe9 conferido primeiro. S\xf3 a leitura do corpo vem antes da busca: o campo n\xe3o anul\xe1vel ausente ou nulo (como o `nome`, ou o `fatoCodigo` de uma exig\xeancia por op\xe7\xe3o) \xe9 recusado com 400, sem c\xf3digo deste cat\xe1logo, antes de o pedido chegar \xe0s regras do Uni+."],"comoResolver":["Confira o identificador do modelo na listagem (`GET /api/configuracao/admin/modelos-formulario`), que traz os modelos ativos e os desativados. Se o modelo nunca foi cadastrado, cadastre-o (`POST /api/configuracao/admin/modelos-formulario`)."],"ondeAparece":["Atualiza\xe7\xe3o de um modelo de formul\xe1rio, com identificador que n\xe3o resolve","Ativa\xe7\xe3o de um modelo de formul\xe1rio, com identificador que n\xe3o resolve","Desativa\xe7\xe3o de um modelo de formul\xe1rio, com identificador que n\xe3o resolve"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Modelo formulario"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"0258f07cac6c9b7f9d70290a4b0385549eb99572"}}')}}]);